def scale_free_graph(n: int, m: int, rng: random.Random) -> List[List[int]]:
    if n <= 0 or m <= 0:
        return [[] for _ in range(max(0, n))]
    adj = [set() for _ in range(n)]
    # start with a small fully connected core of size m+1
    core = min(n, m + 1)
    for i in range(core):
        for j in range(i + 1, core):
            adj[i].add(j); adj[j].add(i)
    degree = [len(adj[i]) for i in range(n)]
    total_degree = sum(degree)
    for new in range(core, n):
        targets = set()
        while len(targets) < min(m, new):
            # preferential attachment
            r = rng.uniform(0, max(1e-9, total_degree))
            acc = 0.0
            picked = 0
            for i in range(new):
                acc += degree[i]
                if acc >= r:
                    picked = i
                    break
            if picked != new:
                targets.add(picked)
        for t in targets:
            adj[new].add(t); adj[t].add(new)
        degree[new] = len(adj[new])
        total_degree += degree[new] + sum(1 for _ in targets)
    return [list(s) for s in adj]

