class InformationAndBeliefModule(ModuleBase):
    def forward(self, state, buffers, params, t):
        media: Media = state["media"]
        gov: Government = state["government"]
        credible_hits = {}
        misinfo_hits = {}
        person_updates = {}
        for p in state["persons"]:
            saw_media = self.rng.random() < media.reach
            cred = saw_media and (self.rng.random() < media.credibility)
            mis = saw_media and (self.rng.random() < params.get("misinformation_fraction", 0.15))
            credible_hits[p.id] = 1 if cred else 0
            misinfo_hits[p.id] = 1 if mis else 0
            # EWMA update
            decay = float(params.get("belief_update_decay", 0.1))
            new_risk = clamp((1-decay)*p.risk_perception + decay*(params.get("risk_perception_initial_mean", 0.5) + (1.0 if gov.mandate_active else 0.0) + (0.1 if cred else 0.0) - (0.1 if mis else 0.0)), 0.0, 1.0)
            new_trust = clamp((1-decay)*p.trust_in_authority + decay*(media.credibility - (0.2 if mis else 0.0)), 0.0, 1.0)
            person_updates[p.id] = {"risk_perception": new_risk, "trust_in_authority": new_trust}
        signals = buffers.get("signals", {})
        signals["credible_exposure"] = credible_hits
        signals["misinfo_exposure"] = misinfo_hits
        return {"person_updates": person_updates, "signals": signals, "location_updates": {}, "retailer_updates": {}, "global_updates": {}, "observables": {}, "io": {}}

