class RetailMarketModule(ModuleBase):
    def forward(self, state, buffers, params, t):
        intent = buffers.get("signals", {}).get("intent_to_wear_mask", {})
        attempts = 0
        fulfilled = 0
        for p in state["persons"]:
            if not intent.get(p.id, False):
                continue
            attempts += 1
            r = max(state["retailers"], key=lambda x: x.inventory_level) if state["retailers"] else None
            if not r or r.inventory_level <= 0:
                continue
            qty = min(params.get("retailer_rationing_limit_per_purchase", 10), params.get("target_inventory", 5) - p.mask_inventory)
            if qty <= 0:
                continue
            buy = min(qty, r.inventory_level)
            if buy > 0:
                fulfilled += 1
                r.inventory_level -= buy
                p.mask_inventory += buy
        unmet = max(0, attempts - fulfilled)
        eff = unmet / max(1, attempts)
        obs = {"stockouts_daily": sum(1 for r in state["retailers"] if r.inventory_level <= 0), "supply_constraints_effect_daily": eff}
        return {"person_updates": {}, "signals": buffers.get("signals", {}), "location_updates": {}, "retailer_updates": {}, "global_updates": {}, "observables": obs, "io": {}}
